[vAlpha, vBeta, iAlpha, iBeta, p, q] = clarkeAndPower(vA,vB,vC,iLA,iLB,iLC);
buf = [buf(2:end), p];
pbar = wnnForwardEmbedded(buf, v, w, w0, aFix, bFix);

[icRefA, icRefB, icRefC, dcInt] = dcRegAndInvClarke(p, q, pbar, Vdc, VdcRef, Ts, dcInt, vAlpha, vBeta);
end

function y = wnnForwardEmbedded(x, v, w, w0, aFix, bFix)
scale = mean(abs(x)) + 1.0;
xn = x / scale;
z = xn * v;                    % (1 x K)
u = (z - bFix) ./ aFix;
h = (1 - u.^2) .* exp(-0.5*u.^2);
yN = h*w + w0;
y = yN * scale;
end

function [vAlpha,vBeta,iAlpha,iBeta,p,q] = clarkeAndPower(vA,vB,vC,iLA,iLB,iLC)
vAlpha = (2/3)*(vA - 0.5*vB - 0.5*vC);
vBeta  = (2/3)*(sqrt(3)/2)*(vB - vC);
iAlpha = (2/3)*(iLA - 0.5*iLB - 0.5*iLC);
iBeta  = (2/3)*(sqrt(3)/2)*(iLB - iLC);
p = vAlpha*iAlpha + vBeta*iBeta;
q = vAlpha*iBeta  - vBeta*iAlpha;
end

function [icRefA,icRefB,icRefC,dcInt] = dcRegAndInvClarke(p,q,pbar,Vdc,VdcRef,Ts,dcInt,vAlpha,vBeta)
% DC-link voltage regulation (adds active power reference to recharge/
% discharge the capacitor) + full reactive-power compensation (qc = q).
% Tuned for wn=2*pi*8 rad/s, zeta=0.7 with C=2000uF, Vref=800V:
%   Kp = 2*zeta*wn*C*Vref, Ki = wn^2*C*Vref  (units: W/V, W/(V s))
Kp_dc = 112.6; Ki_dc = 4043;
errDc = VdcRef - Vdc;
dcInt = dcInt + Ki_dc*errDc*Ts;
dP = Kp_dc*errDc + dcInt;

pc = p - pbar - dP;   % active power the APF must supply
qc = q;               % APF supplies ALL reactive power (unity PF at source)

denom = vAlpha^2 + vBeta^2 + 1e-6;
icAlpha = (vAlpha*pc - vBeta*qc)/denom;   % inverse of q = va*ib - vb*ia
icBeta  = (vBeta*pc + vAlpha*qc)/denom;

icRefA = icAlpha;
icRefB = -0.5*icAlpha + (sqrt(3)/2)*icBeta;
icRefC = -0.5*icAlpha - (sqrt(3)/2)*icBeta;
end
